{
  "goal": "Add query support for task list/view so users can filter tasks by status, priority, tags, and free-text search while preserving the typed JSON storage boundary.",
  "decisions": [
    "Bun-based CLI entrypoint and minimal argument parsing; CLI dispatch lives in src/cli.ts with per-command handlers.",
    "Persist tasks as a single JSON file at .taskforge/tasks.json (schema version = 1).",
    "Strongly typed Task model (TaskStatus/TaskPriority) extended with optional tags: string[].",
    "Keep storage API command-agnostic (listTasks/getTaskById/upsert/remove) with atomic save via temp-file + rename.",
    "Add a pure query layer: TaskQuery type + filterTasks(tasks, query) — normalize inputs at the CLI boundary (trim/lowercase/split tags)."
  ],
  "risks": [
    "Strict validation of the Task schema (now including tags) may reject hand-edited or older files without a migration path.",
    "Search is simple case-insensitive substring matching — users may expect fuzzy/stemming behavior.",
    "Concurrent writers not addressed; atomic rename helps single-process safety but cross-filesystem/parallel write semantics remain a risk."
  ],
  "snippets": [
    "const STORAGE_PATH = '.taskforge/tasks.json';",
    "type TaskStatus = 'todo' | 'in_progress' | 'done';
type TaskPriority = 'low' | 'medium' | 'high';
type Task = {
  id: string;
  title: string;
  status: TaskStatus;
  priority: TaskPriority;
  createdAt: string;
  updatedAt: string;
  description?: string;
  completedAt?: string;
  tags?: string[];
};",
    "type TaskQuery = { status?: TaskStatus; priority?: TaskPriority; tags?: string[]; search?: string };
function filterTasks(tasks: Task[], q: TaskQuery): Task[] {
  return tasks.filter(t => {
    if (q.status && t.status !== q.status) return false;
    if (q.priority && t.priority !== q.priority) return false;
    if (q.tags) for (const tag of q.tags) if (!t.tags?.map(s=>s.toLowerCase()).includes(tag.toLowerCase())) return false;
    if (q.search) {
      const s = q.search.toLowerCase();
      if (!((t.title||'').toLowerCase().includes(s) || (t.description||'').toLowerCase().includes(s))) return false;
    }
    return true;
  });
}"
  ],
  "invariants": [
    "schema version = 1",
    "storage file = .taskforge/tasks.json"
  ]
}
